func (app *App[P]) golemGeneratedGraphQLBeginCaller(ctx context.Context, principal P) (golemgraphql.CallerExecution, error) {
	if app == nil || app.runtime == nil {
		return nil, fmt.Errorf("GraphQL application is unavailable")
	}
	caller, err := app.ForPrincipal(ctx, principal)
	if err != nil {
		return nil, err
	}
	execution, err := golemruntime.NewCallerMutationExecution(caller.runtime,
		golemruntime.CallerMutationModel[P, Actor](GolemGeneratedCategoryDescriptor),
		golemruntime.CallerMutationModel[P, Actor](GolemGeneratedMetricDescriptor),
	)
	if err != nil {
		return nil, err
	}
	return &golemGeneratedGraphQLCaller[P]{public: caller, execution: execution}, nil
}

func (app *App[P]) GraphQL(config GraphQLConfig[P]) (*GraphQLServer, error) {
	if app == nil || app.runtime == nil {
		return nil, fmt.Errorf("GraphQL application is unavailable")
	}
	bundle := GolemGeneratedSchemaBundle()
	golemGeneratedExecutable := golemgqlgen.NewExecutableSchema(golemgqlgen.Config{Resolvers: &golemgqlgen.Resolver{}})
	executor, err := golemgraphql.NewGeneratedExecutor(golemgraphql.GeneratedExecutorConfig[P]{
		Bundle: bundle, Limits: config.Limits, BeginCaller: app.golemGeneratedGraphQLBeginCaller, ReportInternalError: config.ReportInternalError,
	})
	if err != nil {
		return nil, err
	}
	server, err := golemgraphql.NewServer(golemGeneratedGraphQLSDL, golemgraphql.Config[P]{
		PrincipalFromContext: config.PrincipalFromContext, Limits: config.Limits, Introspection: config.Introspection,
		ContractFingerprint: bundle.Contract().Fingerprint(), ReportInternalError: config.ReportInternalError, ExecutableSchema: golemGeneratedExecutable,
	}, executor)
	if err != nil {
		return nil, err
	}
	return &GraphQLServer{handler: server.Handler(), sdl: server.SDL(), contractFingerprint: server.ContractFingerprint()}, nil
}
